import { useEffect, useState } from "react";
import { Button } from "@tailrocks/framerock/ui/button";
import { Toaster } from "@tailrocks/framerock/ui/sonner";
import { defineStory } from "../../lib/story";

function SonnerStory({
  message = "Evaluation run queued",
  description = "Results will stream into the trace table.",
}: {
  message?: string;
  description?: string;
}) {
  const [visible, setVisible] = useState(true);
  const [tone, setTone] = useState<"success" | "error">("success");

  useEffect(() => {
    setVisible(true);
    setTone("success");
  }, [message, description]);

  return (
    <div className="relative flex min-h-48 w-full max-w-md flex-col items-start justify-between rounded-xl border bg-muted/15 p-4">
      <div className="flex flex-wrap gap-2">
        <Button
          type="button"
          size="sm"
          onClick={() => {
            setTone("success");
            setVisible(true);
          }}
        >
          Trigger toast
        </Button>
        <Button
          type="button"
          size="sm"
          variant="outline"
          onClick={() => {
            setTone("error");
            setVisible(true);
          }}
        >
          Error toast
        </Button>
      </div>
      {visible ? (
        <div
          role="status"
          aria-live="polite"
          className="mt-4 flex w-full items-start justify-between gap-3 rounded-lg border bg-popover p-3.5 text-popover-foreground shadow-md"
        >
          <div className="grid gap-1">
            <div className="text-xs font-medium">
              {tone === "error" ? "Judge timeout" : message}
            </div>
            <div className="text-xs text-muted-foreground">
              {tone === "error" ? "Retrying with fallback model." : description}
            </div>
          </div>
          <Button variant="ghost" size="xs" onClick={() => setVisible(false)}>
            Dismiss
          </Button>
        </div>
      ) : null}
      <Toaster />
    </div>
  );
}

export const story = defineStory({
  id: "primitives/sonner",
  registryItem: "ui-sonner",
  displayName: "Sonner",
  Component: SonnerStory,
  frame: { height: 280 },
  args: [
    { variant: "Default", initial: { message: "Evaluation run queued", description: "Results will stream into the trace table." } },
    { variant: "Export notice", initial: { message: "Trace export ready", description: "Downloaded 148 spans as JSONL." } },
  ],
});
